-- MySQL 8+. Select your target database before running this file.
-- Missing prices/ratings are SQL NULL. Menu portions are NOT assumed to be per person.
SET NAMES utf8mb4;
SET @busan_previous_sql_mode = @@SESSION.sql_mode;
SET SESSION sql_mode = 'NO_BACKSLASH_ESCAPES,STRICT_TRANS_TABLES';
CREATE TABLE IF NOT EXISTS public_busan_places (
 place_id VARCHAR(80) PRIMARY KEY, name VARCHAR(500) NOT NULL, branch VARCHAR(500),
 category VARCHAR(30), industry_code VARCHAR(30), industry_name VARCHAR(300),
 province VARCHAR(50), district VARCHAR(100), neighborhood VARCHAR(100),
 road_address TEXT, lot_address TEXT, lat DOUBLE NULL, lon DOUBLE NULL,
 phone VARCHAR(200), website TEXT, price_krw INT NULL, price_basis VARCHAR(100),
 rating DOUBLE NULL, review_count INT NULL, source_dataset VARCHAR(30),
 source_record_id VARCHAR(100), source_reference_date DATE NULL, source_url VARCHAR(500),
 INDEX idx_busan_category(category), INDEX idx_busan_district(district)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS public_busan_price_shops (
 price_shop_id VARCHAR(80) PRIMARY KEY, linked_place_id VARCHAR(80) NULL,
 name VARCHAR(500), district VARCHAR(100), industry_name VARCHAR(300), address TEXT,
 match_method VARCHAR(50), source_dataset VARCHAR(30), source_reference_date DATE,
 source_url VARCHAR(500), FOREIGN KEY(linked_place_id) REFERENCES public_busan_places(place_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS public_busan_menu_prices (
 menu_id VARCHAR(80) PRIMARY KEY, price_shop_id VARCHAR(80) NOT NULL,
 menu_name TEXT, price_krw INT NULL, price_raw TEXT, price_basis VARCHAR(100),
 FOREIGN KEY(price_shop_id) REFERENCES public_busan_price_shops(price_shop_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
